<?php use ImWiki\Security\Csrf; use ImWiki\Security\Html; use ImWiki\Support\Url; $title='Logowanie'; ?>
<section class="auth-wrap"><div class="card auth-card"><h1>Zaloguj się do imWiki</h1><?php if($error): ?><div class="alert danger"><?=Html::e($error)?></div><?php endif; ?><form method="post" action="<?=Html::e(Url::to('/login'))?>"><?=Csrf::field()?><label>Login lub e-mail<input name="login" autocomplete="username" required autofocus></label><label>Hasło<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Zaloguj się</button></form><p><a href="<?=Html::e(Url::to('/forgot-password'))?>">Nie pamiętam hasła</a></p></div></section>
